import React, { HTMLAttributes } from 'react';

import * as L from 'leaflet';

import 'leaflet/dist/leaflet.css';

import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { getWorkoutTypeColor } from '@apps/Workouts/@helpers/workouts.helper';
import { IWorkout } from '@apps/Workouts/@types/workouts.types';
import { dateRangeToLocaleString, getDiffDate } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';
import { getDefaultTileLayer, getMap, setDefaultMapView } from '@helpers/leafletHelper';

interface IActivitiesMapProps extends HTMLAttributes<HTMLDivElement> {
  activities: IWorkout[];
  onTrackClick: (workout: IWorkout) => void;
}

const ActivitiesMap = ({ activities, onTrackClick, ...rest }: IActivitiesMapProps) => {
  const mapContainerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);
  const layersRef = React.useRef<L.FeatureGroup>(new L.FeatureGroup());

  React.useEffect(() => {
    if (!mapContainerRef.current) return;
    mapRef.current = getMap(mapContainerRef.current);

    getDefaultTileLayer().addTo(mapRef.current);
    setDefaultMapView(mapRef.current);
    watermarkToMap(mapRef.current);

    layersRef.current.addTo(mapRef.current);
  }, []);

  React.useEffect(() => {
    layersRef.current.clearLayers();
    activities.forEach((a) => {
      const pl = new L.Polyline(a.points, { color: getWorkoutTypeColor(a.type.id), opacity: 0.5 });
      pl.bindTooltip(
        [
          a.type.name,
          dateRangeToLocaleString(a.date_start, a.date_finish),
          formatDistance(a.distance),
          getDiffDate(a.date_start, a.date_finish).toLocaleTimeString(),
        ].join('\n'),
      );
      pl.on('click', () => onTrackClick(a));
      pl.addTo(layersRef.current);
    });

    const bounds = layersRef.current.getBounds();
    if (bounds.isValid()) {
      mapRef.current?.fitBounds(bounds);
    }
    //
  }, [activities]);

  return <div {...rest} ref={mapContainerRef} />;
};

export default ActivitiesMap;
